REFERENCE_SHA256 = 'aeb24bba3f74b13036d2d12a98a25dd1a8fd68950e04494ab26fefef7cc0c4e6'


def _run(name, fixture):
    return getattr(checkers, name)(FIXTURES[fixture])


def test_target_reached_on_reexecuted_seeds():
    """Accepting half on the reference, rejecting half on the planted fixture."""
    accepted = _run('check_target_reached_on_reexecuted_seeds', 'reference')
    assert accepted.value == 1.0, 'target_reached_on_reexecuted_seeds rejected the reference: ' + accepted.detail
    rejected = _run('check_target_reached_on_reexecuted_seeds', 'defect_no_target_reached')
    assert rejected.value < 1.0, 'target_reached_on_reexecuted_seeds accepted a planted defect'
    assert rejected.reason == 'screen-target-not-reached', rejected.reason


